!function(){"use strict";window.aipkit_cloudCreditNoticeBound||(window.aipkit_cloudCreditNoticeBound=!0,document.addEventListener("click",async e=>{let t=e.target.closest("[data-cloud-credit-dismiss]");if(!t||t.disabled)return;let d=t.closest(".aipkit_cloud_credit_notice"),i=d.querySelector("[data-cloud-credit-feedback]");t.disabled=!0,i.hidden=!0;try{let e=new FormData;e.append("action","aipkit_dismiss_cloud_credit_notice"),e.append("_ajax_nonce",d.dataset.cloudCreditNonce),e.append("key",d.dataset.cloudCreditKey),e.append("fingerprint",d.dataset.cloudCreditFingerprint);let t=await fetch(d.dataset.cloudCreditUrl,{method:"POST",credentials:"same-origin",body:e}),i=await t.json();if(!t.ok||!i?.success)throw new Error(i?.data?.message||d.dataset.cloudCreditError);d.remove()}catch(e){i.textContent=e.message,i.hidden=!1}finally{t.disabled=!1}}))}();